class Solution {
public:
    bool checkXMatrix(std::vector<std::vector<int>>& grid) {
        int n = grid.size();
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                bool is_diag = (r == c || r + c == n - 1);
                if (is_diag && grid[r][c] == 0) return false;
                if (!is_diag && grid[r][c] != 0) return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                boolean isDiag = (r == c || r + c == n - 1);
                if (isDiag && grid[r][c] == 0) return false;
                if (!isDiag && grid[r][c] != 0) return false;
            }
        }
        return true;
    }
}

var checkXMatrix = function(grid) {
    const n = grid.length;
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const isDiag = (r === c || r + c === n - 1);
            if (isDiag && grid[r][c] === 0) return false;
            if (!isDiag && grid[r][c] !== 0) return false;
        }
    }
    return true;
};
